```js
(function (global) {
  'use strict';
  var namespace = global.SnakeGame = global.SnakeGame || {};

  var DEFAULT_SPEED_CPS = 7;
  var MAX_CATCH_UP_STEPS = 5;

  function createLoop(options) {
    var opts = options || {};
    var tickFn = typeof opts.tick === 'function' ? opts.tick : function () {};
    var drawFn = typeof opts.draw === 'function' ? opts.draw : function () {};
    var nowFn = typeof opts.now === 'function' ? opts.now : defaultNow;

    var running = false;
    var paused = false;
    var rafId = null;
    var lastTime = 0;
    var accumulator = 0;
    var speedCps = DEFAULT_SPEED_CPS;
    var requestFrame = ...; cancelFrame...

    function defaultNow() {
      if (typeof performance !== 'undefined' && typeof performance.now === 'function') return performance.now();
      return Date.now ? Date.now() : 0;
    }

    function frame() {
      rafId = null;
      if (!running) return;
      var time = Number(nowFn());
      if (!isFinite(time)) time = lastTime;
      var delta = time - lastTime;
      lastTime = time;
      if (delta < 0) delta = 0;

      if (!paused) {
        accumulator += delta;
        var stepMs = 1000 / speedCps;
        if (!(stepMs > 0) || !isFinite(stepMs)) stepMs = 1000 / DEFAULT_SPEED_CPS;
        var steps = Math.floor(accumulator / stepMs);
        if (steps > 0) {
          if (steps > MAX_CATCH_UP_STEPS) {
            // 超出单帧追赶上限：丢弃积压，只补 5 步，避免突跳
            steps = MAX_CATCH_UP_STEPS;
            accumulator = 0;
          } else {
            accumulator -= steps * stepMs;
          }
          for (var i = 0; i < steps; i++) {
            var outcome = tickFn();
            if (outcome && typeof outcome === 'object' && isFinite(outcome.speedCps) && outcome.speedCps > 0) {
              speedCps = outcome.speedCps;
            }
          }
        }
      }
      // 每帧重绘一次（暂停时也可重绘）
      try { drawFn(); } catch (e) { /* 不打断循环 */ }
      schedule();
    }
```

